CREATE TYPE public.app_role AS ENUM ('learner', 'educator', 'admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'learner', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', camp text CHECK(camp IN ('Ifo','Hagadera','Dagahaley')), educator_requested boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin'))) WITH CHECK(id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE FUNCTION public.protect_profile_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.active IS DISTINCT FROM OLD.active AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only administrators can change account status'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_status BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_status();
CREATE FUNCTION public.is_active_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active AND camp IS NOT NULL) $$;
REVOKE EXECUTE ON FUNCTION public.is_active_member() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_active_member() TO authenticated,service_role;
CREATE FUNCTION public.create_aqoon_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,camp,educator_requested) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name',''),CASE WHEN NEW.raw_user_meta_data->>'camp' IN ('Ifo','Hagadera','Dagahaley') THEN NEW.raw_user_meta_data->>'camp' ELSE NULL END,coalesce(NEW.raw_user_meta_data->>'account_type','')='educator'); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'learner'); RETURN NEW; END $$;
CREATE TRIGGER on_aqoon_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_aqoon_profile();
CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), educator_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, title text NOT NULL CHECK(length(title)>2), description text NOT NULL DEFAULT '', category text NOT NULL CHECK(category IN ('Digital Skills','Languages','Business','Life Skills')), level text NOT NULL DEFAULT 'Beginner', duration text NOT NULL DEFAULT 'Self-paced', image_key text NOT NULL DEFAULT 'classroom', cover_path text, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.courses TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY courses_public ON public.courses FOR SELECT TO anon USING(published);
CREATE POLICY courses_read ON public.courses FOR SELECT TO authenticated USING(published OR educator_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY courses_insert ON public.courses FOR INSERT TO authenticated WITH CHECK((select public.is_active_member()) AND (educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator')) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY courses_update ON public.courses FOR UPDATE TO authenticated USING((select public.is_active_member()) AND (educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator')) OR (select public.has_role((select auth.uid()),'admin')))) WITH CHECK((select public.is_active_member()) AND (educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator')) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY courses_delete ON public.courses FOR DELETE TO authenticated USING((select public.is_active_member()) AND (educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator')) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE INDEX courses_educator_idx ON public.courses(educator_id,created_at DESC);
CREATE TABLE public.enrolments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,course_id));
GRANT SELECT,INSERT,DELETE ON public.enrolments TO authenticated; GRANT ALL ON public.enrolments TO service_role;
ALTER TABLE public.enrolments ENABLE ROW LEVEL SECURITY;
CREATE POLICY enrolments_read ON public.enrolments FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY enrolments_insert ON public.enrolments FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()) AND (select public.is_active_member()) AND EXISTS(SELECT 1 FROM public.courses WHERE id=course_id AND published));
CREATE POLICY enrolments_delete ON public.enrolments FOR DELETE TO authenticated USING(user_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE INDEX enrolments_course_idx ON public.enrolments(course_id);
CREATE TABLE public.lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title)>0), content text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 1, attachment_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.lessons TO authenticated; GRANT ALL ON public.lessons TO service_role;
ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY lessons_read ON public.lessons FOR SELECT TO authenticated USING((select public.is_active_member()) AND (course_id IN (SELECT course_id FROM public.enrolments WHERE user_id=(select auth.uid())) OR course_id IN (SELECT id FROM public.courses WHERE educator_id=(select auth.uid())) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY lessons_insert ON public.lessons FOR INSERT TO authenticated WITH CHECK((select public.is_active_member()) AND (course_id IN (SELECT id FROM public.courses WHERE educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator'))) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY lessons_update ON public.lessons FOR UPDATE TO authenticated USING((select public.is_active_member()) AND (course_id IN (SELECT id FROM public.courses WHERE educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator'))) OR (select public.has_role((select auth.uid()),'admin')))) WITH CHECK((select public.is_active_member()) AND (course_id IN (SELECT id FROM public.courses WHERE educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator'))) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY lessons_delete ON public.lessons FOR DELETE TO authenticated USING((select public.is_active_member()) AND (course_id IN (SELECT id FROM public.courses WHERE educator_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'educator'))) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE INDEX lessons_course_idx ON public.lessons(course_id,position);
CREATE POLICY course_media_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='course-media' AND (storage.foldername(name))[1]=(select auth.uid())::text AND (select public.is_active_member()) AND ((select public.has_role((select auth.uid()),'educator')) OR (select public.has_role((select auth.uid()),'admin'))));
CREATE POLICY course_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='course-media' AND (select public.is_active_member()) AND ((storage.foldername(name))[1]=(select auth.uid())::text OR (select public.has_role((select auth.uid()),'admin')) OR name IN (SELECT cover_path FROM public.courses WHERE published) OR name IN (SELECT attachment_path FROM public.lessons)));
INSERT INTO public.courses(id,title,description,category,duration,image_key,published) VALUES
('10000000-0000-4000-8000-000000000001','Computer & Digital Essentials','Build confidence with computers, the internet and the digital tools you use every day. Start with the basics and practise useful skills at your own pace.','Digital Skills','4 lessons · Self-paced','classroom',true),
('10000000-0000-4000-8000-000000000002','English for Everyday Life','Find your voice in English. Practise introductions, everyday conversations and the words you need for learning and work.','Languages','4 lessons · Self-paced','students',true),
('10000000-0000-4000-8000-000000000003','Start Your Small Business','Turn an idea into a practical plan. Learn to understand customers, calculate costs and keep simple business records.','Business','4 lessons · Self-paced','computers',true);
INSERT INTO public.lessons(course_id,title,content,position) VALUES
('10000000-0000-4000-8000-000000000001','Getting to know a computer','A computer helps you create documents, find information and communicate. The monitor displays information, the keyboard enters text and the mouse moves the pointer.\n\nPractice: identify each part. Open a text editor, type your name and save your document as My first document. Close it, then find and reopen it. Never share your account password.',1),
('10000000-0000-4000-8000-000000000001','Files and folders','A file stores a document or photograph. A folder groups related files. Use clear names so you can find your work.\n\nPractice: create a folder called Learning. Move your first document into it. Make a second document with your learning goals. Save a backup on a trusted drive when available.',2),
('10000000-0000-4000-8000-000000000001','Using the internet safely','A browser opens websites. Check the address before entering personal information. A secure connection uses HTTPS, but it does not guarantee a website is honest.\n\nNever send money or passwords to someone who promises a prize. Avoid unknown downloads. Practice searching for a topic and comparing two reliable sources.',3),
('10000000-0000-4000-8000-000000000001','Writing your first email','An email has a recipient, subject and message. Keep the subject clear, begin with a greeting and finish with your name.\n\nPractice: draft an email asking an educator about a lesson. Read it before sending. Check the recipient and any attachment. Sign out when using a shared computer.',4),
('10000000-0000-4000-8000-000000000002','Introducing yourself','Try these sentences: Hello, my name is ___. I live in ___. I am learning English. It is nice to meet you.\n\nPractice: say each sentence aloud. Write a short introduction, then practise it with a friend. Ask: What is your name? What do you like learning?',1),
('10000000-0000-4000-8000-000000000002','Asking for help','Useful phrases: Could you help me, please? I do not understand. Could you repeat that? Where can I find the classroom?\n\nPractice: take turns being a learner and an educator. Ask for directions, then repeat what you heard to check your understanding.',2),
('10000000-0000-4000-8000-000000000002','Everyday conversations','Use questions to begin a conversation: How are you? What are you studying? What time does the lesson start?\n\nPractice: write a six-line conversation with a greeting, two questions and a goodbye. Read it aloud with a partner.',3),
('10000000-0000-4000-8000-000000000002','Talking about your goals','Say: I want to learn ___. My goal is to ___. I practise every ___.\n\nPractice: write three goals for the next month. Describe one small action you can take each week. Share your goals in English with a friend.',4),
('10000000-0000-4000-8000-000000000003','Find a useful business idea','A useful business solves a problem for customers. Think about what people need, what skills you have and what resources are available.\n\nPractice: list three ideas. For each, write who the customer is and what problem you would solve. Talk to potential customers before spending money.',1),
('10000000-0000-4000-8000-000000000003','Know your customers','Ask customers what they need, how they currently solve the problem and what they can afford. Listen without promising something you cannot deliver.\n\nPractice: write five interview questions. Speak to three potential customers. Compare what they say and choose the most common need.',2),
('10000000-0000-4000-8000-000000000003','Calculate costs and prices','Revenue is the money customers pay. Costs are what you spend. Profit equals revenue minus costs. Include materials, transport and other expenses.\n\nExample: selling an item for KES 150 with costs of KES 100 leaves KES 50 before any other expenses. Practice calculating costs for your own idea.',3),
('10000000-0000-4000-8000-000000000003','Keep simple records','Record the date, description, money received and money spent for every transaction. Keep receipts where possible. Separate business money from personal spending.\n\nPractice: create a weekly record with five example transactions. Add income and expenses, then calculate the difference. Use the results to plan the next week.',4);